import * as z from "zod";

export const schema = z
  .object({
    summary: z.string().min(1, "Summary is required.").meta({
      title: "Summary",
      description:
        "A short introduction shown at the top of the results page and used as its search result description.",
    }),
    results: z
      .array(
        z
          .object({
            id: z.string().min(1, "ID is required.").meta({
              title: "ID",
              description:
                "A hidden stable identifier generated by the setup page.",
            }),
            slugs: z
              .array(
                z
                  .object({
                    isActive: z.boolean().default(true).meta({
                      title: "Is Active",
                      description:
                        "Whether this slug is active and should be used to access the result.",
                    }),
                    slug: z.string().min(1, "Slug is required.").meta({
                      title: "Slug",
                      description:
                        "A unique URL slug generated from the result title.",
                    }),
                  })
                  .meta({
                    title: "Slug",
                    description:
                      "A unique URL slug generated from the result title.",
                  }),
              )
              .default([])
              .meta({
                title: "Slugs",
                description:
                  "The list of slugs including historical ones that can be used to access the result.",
              }),
            title: z.string().min(1, "Title is required.").meta({
              title: "Title",
              description:
                "The name of the result, e.g. 'Final Exam 2026', 'Mid-term Results 2025'.",
            }),
          })
          .meta({
            title: "Result",
            description:
              "Metadata for a result entry. Detailed content and attachments are stored in a separate file named after its ID.",
          }),
      )
      .default([])
      .meta({
        title: "Results",
        description: "The list of exam results displayed on the results page.",
      }),
  })
  .meta({
    title: "Results Configuration",
    description: "Configuration for the results page and its result entries.",
  });

export const buildSchema = schema
  .extend({
    summary: z.string(),
  })
  .partial();

export type TInput = z.input<typeof schema>;
export type TOutput = z.output<typeof schema>;
export type TModel = TOutput;

export const defaultValues: TInput = {
  summary: "",
  results: [],
};
